const D = { scale:1, energy:.6, hue:38, speed:1, density:.5, x:.5, y:.83, pose:'sweep', style:'sumi', act:'courtyard', stoop:.5, robe:.55, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
const sn=(tt,off)=>{const f=Math.floor(tt),xq=tt-f; return (fr(f+off)*(1-xq)+fr(f+1+off)*xq-.5)*2;};
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat;
S.lastBeat=K.beat;

const u=Math.min(width,height);
const sc=u*P.scale/440;            // figure ~200 local tall -> ~0.45u
const bt=K.beat*P.speed;
const en=P.energy*(.55+.55*K.intensity);
const H=md(P.hue,360);
const sil=P.style==='silhouette', char=P.style==='charcoal', scroll=P.style==='scroll';
const sumi=!sil&&!char&&!scroll;

// ---- seed caches ----
if (S.seedUsed!==P.seed){
  S.seedUsed=P.seed;
  S.leaf=[];
  for(let i=0;i<44;i++) S.leaf.push({x:(fr(i*3+1)-.5)*360, y:-fr(i*3+2)*4, vx:0, vy:0, rot:fr(i*5+3)*6.2832, spin:(fr(i*7+4)-.5)*.25, sz:5+fr(i*9+5)*6, hu:18+fr(i*11+6)*34, settled:1});
  S.speck=[];
  for(let i=0;i<22;i++) S.speck.push({x:(fr(i*13+7)-.5)*54, y:-30-fr(i*17+8)*110, r:.8+fr(i*19+9)*2.4});
  S.seal={dx:96+fr(101)*16, dy:-24-fr(103)*18, rot:(fr(107)-.5)*.18};
}

// ---- pose program ----
let pose=P.pose;
const base=P.pose;
if(base==='sweep' || base==='rake'){
  const ph=md(bt,32);
  if(P.act==='meditation'){
    pose = ph<5 ? base : ph<11 ? 'idle' : ph<15 ? 'bow' : ph<21 ? 'idle' : ph<27 ? base : 'idle';
  } else {
    pose = ph<25 ? base : ph<30 ? 'bow' : 'idle';
  }
}
const isSweep = pose==='sweep'||pose==='rake';
const per = pose==='rake'?2:1;

// ---- motion ----
const breath=Math.sin(K.t*.5)*.5 + K.swell*.4;
const wob=sn(K.t*.6,40);
let strokeE=0, lean=0, sway=0, armReach=0, bowD=0;
if(isSweep){
  const c=md(bt,per)/per;
  strokeE=Math.pow(Math.sin(c*Math.PI),1.2);
  lean = strokeE*(.4+.2*en) + P.stoop*.3;
  sway = Math.sin(bt*Math.PI/(per*2))*(14+9*en) + wob*2;
  armReach = strokeE*(.4+.3*en);
} else if(pose==='bow'){
  bowD = clp(.5+K.swell*.35,0,1);
  lean = .95 + P.stoop*.2 + bowD*.15;
  sway = wob*3;
} else { // idle
  lean = P.stoop*.22 + breath*.05;
  sway = Math.sin(bt*Math.PI*.5)*3*en + wob*2;
  armReach = breath*.06;
}
lean += A.bass*.06;
const scatter = K.pulse*.3*en + A.treble*.5;

// broom geometry (upper-frame coords, hip at figure y=-70)
const cL=Math.cos(lean), sL=Math.sin(lean);
let btx=24+strokeE*16, bty=74;
if(isSweep) btx += Math.sin(bt*Math.PI/per)*15;
const tipX = sway + btx*cL - bty*sL;   // figure-local ground x of broom tip
if(S.prevTip==null) S.prevTip=tipX;
const tipV=tipX-S.prevTip; S.prevTip=tipX;

// ---- leaf physics ----
const nLeaf=Math.round(4+P.density*30);
for(let i=0;i<nLeaf;i++){
  const L=S.leaf[i];
  L.vy+=.5;
  if(isSweep){
    const dx=L.x-tipX;
    if(Math.abs(dx)<44 && L.y>-22){
      L.vx += (Math.sign(tipV||dx)*Math.abs(tipV)*.55) + dx*.02;
      L.vy -= 2.0;
    }
  }
  L.vx += sn(K.t*.8+i,i)*.05;
  if(scatter>.5 && fr(i*31+Math.floor(K.beat))<scatter*.28){ L.vy -= scatter*3; L.vx += (fr(i*13+9)-.5)*4; }
  L.vx=clp(L.vx,-13,13); L.vy=clp(L.vy,-13,13);
  L.x+=L.vx; L.y+=L.vy; L.rot+=L.spin+L.vx*.012;
  L.vx*=.9; L.vy*=.86;
  if(L.y>0){ L.y=0; L.vy*=-.2; L.vx*=.7; }
  if(L.x<-200) L.x+=400; if(L.x>200) L.x-=400;
}

// ---- ink helpers ----
function inkFill(dark,a){
  if(sil){ fill(28,12,7,a); return; }
  if(scroll){ fill(H,32,clp(80-dark*48,8,92),a); return; }
  if(char){ fill(0,0,clp(42-dark*34,4,60),a); return; }
  fill(0,0,clp(32-dark*27,3,62),a);
}
function inkStroke(a,w){
  if(sil){ noStroke(); return; }
  if(scroll) stroke(24,52,34,a);
  else if(char) stroke(0,0,14,a);
  else stroke(0,0,9,a);
  strokeWeight(w);
}
function skin(a){
  if(sil){ fill(28,12,8,a); return; }
  if(char){ fill(0,0,54,a); return; }
  fill(28,23,85,a);
}

// ================= DRAW =================
push();
translate(P.x*width, P.y*height);
scale(sc);

// ground shadow wash
noStroke();
inkFill(1, sil?24:14);
ellipse(sway*.5, 3, 168+Math.abs(sway)*.8, 22);
inkFill(1, sil?16:9);
ellipse(tipX, 2, 40, 12);

// leaves behind
noStroke();
for(let i=0;i<nLeaf;i++){ if(i%2) continue; const L=S.leaf[i];
  push(); translate(L.x,L.y-2); rotate(L.rot);
  if(sil) fill(28,12,10,90); else if(char) fill(0,0,30,80); else fill(L.hu,scroll?70:64,scroll?70:60,80);
  beginShape(); vertex(0,-L.sz*.5); bezierVertex(L.sz*.4,-L.sz*.2,L.sz*.4,L.sz*.3,0,L.sz*.5); bezierVertex(-L.sz*.4,L.sz*.3,-L.sz*.4,-L.sz*.2,0,-L.sz*.5); endShape(CLOSE);
  pop();
}

// ---- monk body ----
push();
translate(sway,0);

// lower robe (skirt)
(function(){
  const hemW=60*(.7+P.robe*.7), hipW=28;
  push(); rotate(lean*.22);
  for(let k=3;k>=1;k--){ inkFill(.5+.12*k, (sumi?15:sil?92:24)-k*3);
    noStroke();
    beginShape();
    vertex(-hipW*.6,-66);
    bezierVertex(-hipW-6,-40,-hemW*.72,-14,-hemW-k*3,-2);
    vertex(hemW+k*3,-2);
    bezierVertex(hemW*.72,-14,hipW+6,-40,hipW*.6,-66);
    endShape(CLOSE);
  }
  inkFill(.72, sil?100:80); noStroke();
  beginShape();
  vertex(-hipW*.6,-66);
  bezierVertex(-hipW-4,-40,-hemW*.72,-14,-hemW,-2);
  vertex(hemW,-2);
  bezierVertex(hemW*.72,-14,hipW+4,-40,hipW*.6,-66);
  endShape(CLOSE);
  if(!sil){
    inkStroke(char?46:28,1.2); noFill();
    for(let i=-2;i<=2;i++){ const fxx=i*hemW*.3; line(fxx*.35,-58,fxx,-4); }
    if(char){ inkStroke(20,.8); for(let i=-3;i<=3;i++){ line(i*14,-56,i*14+18,-6); } }
  }
  pop();
})();

// upper body (torso/head/arms) leaning from hip at y=-70
push();
translate(0,-70);
rotate(lean);

// torso robe
inkFill(.66, sil?100:76); noStroke();
beginShape();
vertex(-20,6);
bezierVertex(-26,-24,-22,-48,-16,-64);
vertex(16,-64);
bezierVertex(22,-48,26,-24,20,6);
endShape(CLOSE);

// kasaya sash — the single color note (saffron)
if(!char){
  fill(sil?28:H, sil?12:(scroll?58:66), sil?8:(sumi?72:80), sil?100:90); noStroke();
  beginShape();
  vertex(-18,-58); vertex(5,-64);
  vertex(13,-24); vertex(21,4);
  vertex(6,6); vertex(-2,-22);
  endShape(CLOSE);
  if(!sil){ inkStroke(28,1); noFill(); for(let i=0;i<3;i++) line(-13+i*9,-52+i*2, 3+i*9,-22+i*2); }
}

// arms to broom grip (grip near 10,-4 in this frame)
const gx=10+armReach*10, gy=-4+armReach*4;
(function(){
  inkStroke(sil?100:44, 6); if(sil) stroke(28,12,8);
  noFill();
  const sxL=-14,syL=-58, sxR=14,syR=-58;
  const mxL=(sxL+gx)*.5-2,myL=(syL+gy)*.5+8;
  const mxR=(sxR+gx)*.5+2,myR=(syR+gy)*.5+6;
  beginShape(); vertex(sxL,syL); quadraticVertex(mxL,myL,gx-3,gy); endShape();
  beginShape(); vertex(sxR,syR); quadraticVertex(mxR,myR,gx+3,gy); endShape();
  noStroke(); skin(100); ellipse(gx,gy,8,8);
})();

// broom (handle + straw), tip at (btx,bty)
(function(){
  inkStroke(sil?100:44,3.6); if(sil) stroke(28,12,9);
  line(gx,gy, btx,bty-16);
  const ang=Math.atan2(bty-16-(bty), btx-btx); // vertical-ish; draw straw as fan
  push(); translate(btx,bty-16);
  const spread=strokeE*Math.sign(tipV||1)*10;
  for(let i=-5;i<=5;i++){
    inkStroke(sil?100:(char?46:52),1.5); if(sil) stroke(28,12,9);
    line(i*1.6,0, i*3.4+spread, 16+(5-Math.abs(i))*1.6);
  }
  noStroke(); inkFill(.4, sil?100:70);
  beginShape(); vertex(-9,0); vertex(9,0); vertex(13+spread,15); vertex(-13+spread,15); endShape(CLOSE);
  pop();
})();

// neck + head
inkStroke(sil?100:40,3); if(sil) stroke(28,12,9);
line(-4,-62,-3,-72); line(4,-62,3,-72);
push();
translate(0,-80);
rotate(Math.sin(K.t*.7)*.03 + strokeE*.05 + wob*.02);
noStroke(); skin(100);
beginShape();
vertex(-11,0);
bezierVertex(-13,-16,-8,-27,0,-27);
bezierVertex(8,-27,13,-16,11,0);
bezierVertex(9,9,-9,9,-11,0);
endShape(CLOSE);
skin(100); ellipse(-11,-5,5,8); ellipse(11,-5,5,8);
if(!sil){
  // shaved-head faint dots
  if(sumi||char){ inkStroke(char?30:16,1); for(let r=0;r<2;r++) for(let c=-2;c<=2;c++){ point(c*4, -18-r*5); } }
  inkStroke(70,1.7); noFill();
  line(-7,-6,-3,-5); line(3,-5,7,-6);   // downcast closed eyes
  inkStroke(50,1.2); line(0,-4,-1.5,0); // nose
  inkStroke(45,1.2); line(-2,4,2,4);    // calm mouth
  inkStroke(30,1); line(-8,-9,-4,-10); line(4,-10,8,-9); // brows
}
pop(); // head
pop(); // upper body
pop(); // monk (sway)

// leaves in front
noStroke();
for(let i=0;i<nLeaf;i++){ if(i%2===0) continue; const L=S.leaf[i];
  push(); translate(L.x,L.y-2); rotate(L.rot);
  if(sil) fill(28,12,10,95); else if(char) fill(0,0,34,88); else fill(L.hu,scroll?72:66,scroll?74:64,90);
  beginShape(); vertex(0,-L.sz*.5); bezierVertex(L.sz*.4,-L.sz*.2,L.sz*.4,L.sz*.3,0,L.sz*.5); bezierVertex(-L.sz*.4,L.sz*.3,-L.sz*.4,-L.sz*.2,0,-L.sz*.5); endShape(CLOSE);
  pop();
}

// vermillion seal (sumi/scroll signature)
if(sumi||scroll){
  push(); translate(S.seal.dx,S.seal.dy); rotate(S.seal.rot);
  const br=6+Math.sin(K.t*.4)*.4;
  noFill(); stroke(2,80,78,92); strokeWeight(1.6); rect(-br,-br,br*2,br*2,1);
  stroke(2,78,80,80); strokeWeight(1.2);
  line(-br*.5,-br*.4,br*.5,-br*.4); line(0,-br*.5,0,br*.5); line(-br*.4,br*.3,br*.4,br*.3);
  pop();
}

pop(); // root
